@pytest.mark.asyncio
async def test_async_router_acreate_file_with_jsonl():
    """
    Test router.acreate_file with both JSONL and non-JSONL files
    """
    import json
    from io import BytesIO
    from unittest.mock import MagicMock, patch

    # Create test JSONL content
    jsonl_data = [
        {
            "body": {
                "model": "gpt-3.5-turbo-router",
                "messages": [{"role": "user", "content": "test"}],
            }
        },
        {
            "body": {
                "model": "gpt-3.5-turbo-router",
                "messages": [{"role": "user", "content": "test2"}],
            }
        },
    ]
    jsonl_content = "\n".join(json.dumps(item) for item in jsonl_data)
    jsonl_file = BytesIO(jsonl_content.encode("utf-8"))
    jsonl_file.name = "test.jsonl"

    # Create test non-JSONL content
    non_jsonl_content = "This is not a JSONL file"
    non_jsonl_file = BytesIO(non_jsonl_content.encode("utf-8"))
    non_jsonl_file.name = "test.txt"

    router = litellm.Router(
        model_list=[
            {
                "model_name": "gpt-3.5-turbo-router",
                "litellm_params": {"model": "gpt-3.5-turbo"},
            },
            {
                "model_name": "gpt-3.5-turbo-router",
                "litellm_params": {"model": "gpt-4o-mini"},
            },
        ],
    )

    with patch("litellm.acreate_file", return_value=MagicMock()) as mock_acreate_file:
        # Test with JSONL file
        response = await router.acreate_file(
            model="gpt-3.5-turbo-router",
            purpose="batch",
            file=jsonl_file,
        )

        # Verify mock was called twice (once for each deployment)
        print(f"mock_acreate_file.call_count: {mock_acreate_file.call_count}")
        print(f"mock_acreate_file.call_args_list: {mock_acreate_file.call_args_list}")
        assert mock_acreate_file.call_count == 2

        # Get the file content passed to the first call
        first_call_file = mock_acreate_file.call_args_list[0][1]["file"]
        first_call_content = first_call_file.read().decode("utf-8")

        # Verify the model name was replaced in the JSONL content
        first_line = json.loads(first_call_content.split("\n")[0])
        assert first_line["body"]["model"] == "gpt-3.5-turbo"

        # Reset mock for next test
        mock_acreate_file.reset_mock()

        # Test with non-JSONL file
        response = await router.acreate_file(
            model="gpt-3.5-turbo-router",
            purpose="user_data",
            file=non_jsonl_file,
        )

        # Verify mock was called twice
        assert mock_acreate_file.call_count == 2

        # Get the file content passed to the first call
        first_call_file = mock_acreate_file.call_args_list[0][1]["file"]
        first_call_content = first_call_file.read().decode("utf-8")

        # Verify the non-JSONL content was not modified
        assert first_call_content == non_jsonl_content


@pytest.mark.asyncio
async def test_async_router_acreate_file_passthrough_keeps_the_file_and_forwards_the_flag():
    """A passthrough batch upload must reach the provider byte for byte: the router
    neither rewrites body.model to the deployment model nor drops the flag."""
    from io import BytesIO
    from unittest.mock import MagicMock, patch

    jsonl_content = b'{"custom_id": "r1", "method": "POST", "url": "/v1/chat/completions", "body": {"model": "vertex-batch"}}\n'
    router = litellm.Router(
        model_list=[
            {
                "model_name": "vertex-batch",
                "litellm_params": {"model": "vertex_ai/gemini-2.5-flash", "vertex_project": "p"},
            }
        ],
    )

    with patch("litellm.acreate_file", return_value=MagicMock()) as mock_acreate_file:
        await router.acreate_file(
            model="vertex-batch", purpose="batch", file=BytesIO(jsonl_content), passthrough=True
        )
        forwarded = mock_acreate_file.call_args.kwargs
        assert forwarded["passthrough"] is True
        forwarded["file"].seek(0)
        assert forwarded["file"].read() == jsonl_content

        mock_acreate_file.reset_mock()
        await router.acreate_file(model="vertex-batch", purpose="batch", file=BytesIO(jsonl_content))
        rewritten = mock_acreate_file.call_args.kwargs["file"]
        rewritten.seek(0)
        assert b'"gemini-2.5-flash"' in rewritten.read()


@pytest.mark.asyncio
async def test_async_router_acreate_file_does_not_fall_back_across_model_groups():
    """A file created for batches only exists under the credentials of the model group
    the caller named. A cross-group fallback silently stores it with the wrong provider
    and the later batch create against the named group permanently fails."""
    from unittest.mock import MagicMock, patch

    router = litellm.Router(
        model_list=[
            {
                "model_name": "azure-gpt",
                "litellm_params": {
                    "model": "azure/my-azure-deployment",
                    "api_base": "http://127.0.0.1:9",
                    "api_key": "dummy-key",
                    "api_version": "2024-06-01",
                },
            },
            {
                "model_name": "openai-gpt",
                "litellm_params": {"model": "gpt-4o-mini"},
            },
        ],
        fallbacks=[{"azure-gpt": ["openai-gpt"]}],
    )

    def fail_azure(*args: object, **kwargs: object) -> MagicMock:
        if kwargs.get("model") == "azure/my-azure-deployment":
            raise litellm.APIConnectionError(
                message="Connection error.",
                llm_provider="azure",
                model="azure/my-azure-deployment",
            )
        return MagicMock()

    with patch("litellm.acreate_file", side_effect=fail_azure) as mock_acreate_file:
        with pytest.raises(litellm.APIConnectionError):
            await router.acreate_file(
                model="azure-gpt",
                purpose="batch",
                file=MagicMock(),
            )

        called_models = [call.kwargs.get("model") for call in mock_acreate_file.call_args_list]
        assert "azure/my-azure-deployment" in called_models
        assert "gpt-4o-mini" not in called_models


@pytest.mark.asyncio
async def test_async_router_acancel_batch_does_not_fall_back_across_model_groups(monkeypatch: pytest.MonkeyPatch):
    """The proxy cancels a managed batch by handing the router the deployment id decoded
    from the unified batch id. A default (``*``) fallback matches that id like any other
    model string, and the fallback provider is then asked to cancel a batch it never
    issued, which can only answer not-found. The router re-raises the owner's error after
    that wasted round trip, so the pin's observable is the foreign call never happening."""

    monkeypatch.setattr(litellm, "disable_aiohttp_transport", True)
    router = litellm.Router(
        model_list=[
            {
                "model_name": "azure-gpt",
                "litellm_params": {
                    "model": "azure/my-azure-deployment",
                    "api_base": "http://127.0.0.1:9",
                    "api_key": "dummy-key",
                    "api_version": "2024-06-01",
                },
                "model_info": {"id": "azure-batch-dep"},
            },
            {
                "model_name": "openai-gpt",
                "litellm_params": {"model": "gpt-4o-mini", "api_key": "dummy-key"},
            },
        ],
        default_fallbacks=["openai-gpt"],
    )

    with respx.mock(assert_all_called=False) as respx_mock:
        azure_route = respx_mock.post(host="127.0.0.1").mock(
            return_value=httpx.Response(401, json={"error": {"code": "401", "message": "invalid subscription key"}})
        )
        openai_route = respx_mock.post("https://api.openai.com/v1/batches/batch_owned_by_azure/cancel").mock(
            return_value=httpx.Response(
                404,
                json={
                    "error": {
                        "message": "No batch found with id 'batch_owned_by_azure'.",
                        "type": "invalid_request_error",
                        "code": "batch_not_found",
                    }
                },
            )
        )
        with pytest.raises(openai.AuthenticationError, match="invalid subscription key"):
            await router.acancel_batch(model="azure-batch-dep", batch_id="batch_owned_by_azure")

    assert azure_route.called
