@pytest.mark.asyncio
async def test_acreate_batch_surfaces_owning_provider_error_without_disable_fallbacks():
    """The router itself has to keep a batch inside the group that owns the input file:
    the proxy only sets disable_fallbacks on the managed-files route, so the caller
    otherwise gets the fallback provider's error for a file it never received."""
    from litellm.types.utils import LiteLLMBatch

    router = litellm.Router(
        model_list=[
            {
                "model_name": "owning-model",
                "litellm_params": {
                    "model": "openai/gpt-4o-mini",
                    "api_key": "sk-owning",
                },
            },
            {
                "model_name": "fallback-model",
                "litellm_params": {
                    "model": "azure/gpt-4o-mini",
                    "api_key": "sk-fallback",
                    "api_base": "https://fallback.openai.azure.com",
                    "api_version": "2024-08-01-preview",
                },
            },
        ],
        fallbacks=[{"owning-model": ["fallback-model"]}],
        num_retries=0,
    )
    attempted_models = []

    async def _acreate_batch(model, **kwargs):
        attempted_models.append(model)
        if model == "owning-model":
            raise litellm.APIConnectionError(
                message="Connection error - openai is unreachable",
                model="openai/gpt-4o-mini",
                llm_provider="openai",
            )
        return LiteLLMBatch(
            id="batch-created-on-the-wrong-provider",
            completion_window="24h",
            created_at=0,
            endpoint="/v1/chat/completions",
            input_file_id="file-owned-by-openai",
            object="batch",
            status="validating",
        )

    with patch.object(router, "_acreate_batch", _acreate_batch):
        with pytest.raises(litellm.APIConnectionError, match="openai is unreachable"):
            await router.acreate_batch(
                model="owning-model",
                input_file_id="file-owned-by-openai",
                endpoint="/v1/chat/completions",
                completion_window="24h",
                metadata={"team": "batch-jobs"},
            )

    assert attempted_models == ["owning-model"]


@pytest.mark.asyncio
async def test_acreate_batch_still_falls_back_within_the_owning_model_group():
    """Holding a batch inside the model group that owns its input file must not
    disable fallbacks outright (#35359): the owning group's second deployment is
    still tried in `order`, and only the cross-group target is skipped."""
    completion_window_error = "Invalid value: '5m'. Supported values are: '24h'."
    attempted_models = []

    async def _acreate_batch(**kwargs):
        model = kwargs["model"]
        attempted_models.append(model)
        if model.startswith("azure/"):
            raise litellm.BadRequestError(
                message="Error code: 400 - {'error': {'code': 'quotaExceeded'}}",
                model=model,
                llm_provider="azure",
            )
        raise litellm.BadRequestError(
            message=completion_window_error,
            model=model,
            llm_provider="openai",
        )

    router = litellm.Router(
        model_list=[
            {
                "model_name": "my-gpt",
                "litellm_params": {
                    "model": "openai/gpt-4o-mini",
                    "api_key": "sk-owning",
                    "order": 1,
                },
                "model_info": {"id": "my-gpt-1"},
            },
            {
                "model_name": "my-gpt",
                "litellm_params": {
                    "model": "openai/gpt-4o-mini-backup",
                    "api_key": "sk-owning",
                    "order": 2,
                },
                "model_info": {"id": "my-gpt-2"},
            },
            {
                "model_name": "my-azure-gpt",
                "litellm_params": {
                    "model": "azure/gpt-4o-mini",
                    "api_key": "sk-fallback",
                    "api_base": "https://fallback.openai.azure.com",
                    "api_version": "2024-08-01-preview",
                },
                "model_info": {"id": "my-azure-gpt-1"},
            },
        ],
        fallbacks=[{"my-gpt": ["my-azure-gpt"]}],
        num_retries=0,
    )

    with patch.object(litellm, "acreate_batch", new=_acreate_batch):
        with pytest.raises(litellm.BadRequestError) as raised:
            await router.acreate_batch(
                model="my-gpt",
                input_file_id="file-owned-by-my-gpt",
                endpoint="/v1/chat/completions",
                completion_window="5m",
            )

    assert "24h" in str(raised.value)
    assert "quotaExceeded" not in str(raised.value)
    assert attempted_models == ["openai/gpt-4o-mini", "openai/gpt-4o-mini-backup"]


@pytest.mark.asyncio
async def test_acreate_batch_request_bedrock_tags_override_deployment_tags():
    import httpx

    from litellm.llms.bedrock.common_utils import CommonBatchFilesUtils

    deployment_tags = [{"key": "application", "value": "config-level"}]
    request_tags = [{"key": "application", "value": "request-level"}]
    router = litellm.Router(
        model_list=[
            {
                "model_name": "bedrock-batch-model",
                "litellm_params": {
                    "model": "bedrock/us.anthropic.claude-sonnet-5",
                    "aws_batch_role_arn": "arn:aws:iam::123:role/batch-role",
                    "aws_region_name": "us-west-2",
                    "bedrock_tags": deployment_tags,
                },
            }
        ]
    )

    def fake_response():
        return httpx.Response(
            status_code=200,
            json={
                "jobArn": "arn:aws:bedrock:us-west-2:123:model-invocation-job/abc1234567",
                "status": "Submitted",
            },
        )

    mock_client = MagicMock()
    mock_client.post = AsyncMock(side_effect=lambda *args, **kwargs: fake_response())

    with patch.object(
        CommonBatchFilesUtils,
        "sign_aws_request",
        return_value=({"Authorization": "signed"}, b"{}"),
    ) as mock_sign, patch(
        "litellm.llms.custom_httpx.llm_http_handler.get_async_httpx_client",
        return_value=mock_client,
    ):
        await router.acreate_batch(
            model="bedrock-batch-model",
            input_file_id="s3://bucket/input.jsonl",
            endpoint="/v1/chat/completions",
            completion_window="24h",
        )
        assert mock_sign.call_args.kwargs["data"]["tags"] == deployment_tags

        await router.acreate_batch(
            model="bedrock-batch-model",
            input_file_id="s3://bucket/input.jsonl",
            endpoint="/v1/chat/completions",
            completion_window="24h",
            bedrock_tags=request_tags,
        )
        assert mock_sign.call_args.kwargs["data"]["tags"] == request_tags


@pytest.mark.asyncio
async def test_avector_store_search_injects_router():
    """
    Regression: router.avector_store_search must pass the router down to the
    SDK search call so provider transforms can resolve router-managed
    embedding models (e.g. S3 Vectors query embeddings).
    """
    from litellm.types.vector_stores import VectorStoreSearchResponse

    expected_response = VectorStoreSearchResponse(
        object="vector_store.search_results.page", search_query="q", data=[]
    )
    mock_asearch = AsyncMock(return_value=expected_response)
    # Router.__init__ binds asearch via a local import, so patch the module
    # attribute before constructing the Router.
    with patch("litellm.vector_stores.main.asearch", new=mock_asearch):  # test-quality-ok: the SDK call is the only place the injected router kwarg is observable
        router = litellm.Router(
            model_list=[
                {
                    "model_name": "gpt-3.5-turbo",
                    "litellm_params": {"model": "openai/gpt-3.5-turbo", "api_key": "test-key"},
                }
            ]
        )
        search_response = await router.avector_store_search(
            vector_store_id="v", query="q", custom_llm_provider="s3_vectors"
        )

    assert search_response is expected_response
    mock_asearch.assert_awaited_once()
    assert mock_asearch.await_args.kwargs["router"] is router


@pytest.mark.asyncio
async def test_avector_store_create_does_not_inject_router():
    """The router injection is gated on the search call type: the create path
    must keep calling the SDK without a router kwarg."""
    expected_response = {"id": "vs_1", "object": "vector_store"}
    mock_acreate = AsyncMock(return_value=expected_response)
    # avector_store_create(model=None) resolves acreate via a local import at
    # call time, so patching after Router construction works here.
    router = litellm.Router(
        model_list=[
            {
                "model_name": "gpt-3.5-turbo",
                "litellm_params": {"model": "openai/gpt-3.5-turbo", "api_key": "test-key"},
            }
        ]
    )
    with patch("litellm.vector_stores.main.acreate", new=mock_acreate):  # test-quality-ok: the SDK call is the only place a leaked router kwarg would surface
        create_response = await router.avector_store_create(model=None, custom_llm_provider="openai")

    assert create_response is expected_response
    mock_acreate.assert_awaited_once()
    assert "router" not in mock_acreate.await_args.kwargs


